target as (
  select c.id as category_id, s.id as source_id
  from public.categories c
  join public.sources s on s.category_id=c.id
  where c.slug='technology' and s.slug='technology-archive-evergreen' and s.is_enabled
  limit 1
)
insert into public.source_items (
  source_id, category_id, external_id, prompt, context, refs, instructions, status, source_published_at
)
select
  t.source_id,
  t.category_id,
  m.external_id,
  'Write an original evergreen Blogdel technology article with this exact title: "' || m.title || '".'
    || E'\n\nThe output title must match exactly.'
    || E'\n\nWrite a substantive explainer for a general reader. Do not invent quotations, statistics, studies, or current events.'
    || E'\n\nDo not use em dashes or robot, star, or sparkle icons.'
    
    ,
  jsonb_build_object('headline', m.title, 'published_at', m.target_published_at),
  '[]'::jsonb,
  jsonb_build_object(
      'article_type','explainer',
      'tone','clear',
      'target_length',1000,
      'audience','general',
      'freshness','evergreen',
      'archive_category','technology',
      'image_policy','unique-first-fallback-allowed',
      'no_em_dash',true,
      'prohibited_icons',jsonb_build_array('robot','star','sparkle'),
      'reference_minimum',1
  ),
  'queued'::public.source_item_status,
  m.target_published_at::timestamptz
from manifest m
cross join target t
where not exists (select 1 from public.source_items si where si.external_id=m.external_id);
commit;
